import net.minecraft.world.level.storage.LevelResource;
final class MasterDiamondRuntime {
 static final String QUEST="kingdom_smp:miner/m05";
 static void run(GameTestHelper h)throws Exception{var level=h.getLevel();var server=level.getServer();var mine=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.MINER.buildingId())).findFirst().orElseThrow();var p=server.getPlayerList().getPlayer(mine.owner());h.assertTrue(p!=null,"Original real Master-trial Miner attends");server.getPlayerList().deop(p.getGameProfile());var store=CommerceService.store(server);var track=store.professions(p.getUUID()).track(Profession.MINER);var data=NativeOreSavedData.get(server);var marker=server.getWorldPath(LevelResource.ROOT).resolve("master-diamond-proof.nbt");
  if(track.completedQuestIds().contains(QUEST)){h.assertTrue(track.xp()==3600&&track.completedQuestIds().size()==20&&data.evidence().count(p.getUUID(),ProfessionRank.MASTER,"diamond")==12&&NativeOreQuests.count(p,QUEST)==12&&ConstructionService.structureIntact(level,mine),"Second JVM retains actual12Master diamonds/three regions/20proofs3600XP/original Mine-Doran");CommerceService.verifyReceipt(p);server.tickRateManager().setTickRate(20);com.mojang.logging.LogUtils.getLogger().info("MASTER_DIAMOND_RESTART_PASSED: actual12Master-native diamonds/three regional areas/20earned3600XP/oldApp-J-Nether proofs/global spent/native receipt/Mine-Doran persist");h.succeed();return;}
  h.assertTrue(track.xp()==3300&&track.completedQuestIds().size()==19&&data.evidence().count(p.getUUID(),ProfessionRank.MASTER,"diamond")==0,"Original genuine19proofs, no old Journeyman diamonds reinterpreted as Master");var byChunk=new HashMap<Long,List<BlockPos>>();for(int x=240;x<244;x+=2)for(int z=176;z<180;z+=2)for(var pos:NativeCopperRuntime.generated(h,p,x,z))if(NativeCopperRuntime.metric(p,pos).equals("diamond"))byChunk.computeIfAbsent(ChunkPos.asLong(pos.getX()>>4,pos.getZ()>>4),k->new ArrayList<>()).add(pos);var areas=byChunk.values().stream().sorted(Comparator.comparingInt((List<BlockPos> v)->v.size()).reversed()).toList();h.assertTrue(areas.size()>=3&&areas.get(0).size()+areas.get(1).size()>=11,"Actual future native generation supplies three working diamond regions");int first=Math.min(10,areas.get(0).size());for(var pos:areas.get(0).subList(0,first))NativeCopperRuntime.mine(h,p,pos);for(var pos:areas.get(1).subList(0,11-first))NativeCopperRuntime.mine(h,p,pos);h.assertTrue(data.evidence().count(p.getUUID(),ProfessionRank.MASTER,"diamond")==11&&NativeOreQuests.count(p,QUEST)==0,"Actual first two Master working areas cannot meet three-region proof; old Journeyman regions excluded");NativeCopperRuntime.mine(h,p,areas.get(2).get(0));h.assertTrue(NativeOreQuests.count(p,QUEST)==12,"Actual twelfth native extraction supplies third distinct Master region");CreateCraftRuntime.counter(p,mine);var quote=ProfessionService.review(p,"quest:"+QUEST);ProfessionService.confirm(p,quote.nonce());boolean replay=false;try{ProfessionService.review(p,"quest:"+QUEST);}catch(IllegalStateException expected){replay=true;}h.assertTrue(replay&&store.professions(p.getUUID()).track(Profession.MINER).xp()==3600&&store.professions(p.getUUID()).track(Profession.MINER).completedQuestIds().size()==20,"Canonical once-only300XP retains every prior proof");CommerceService.verifyReceipt(p);AtomicNbt.write(marker,new net.minecraft.nbt.CompoundTag());com.mojang.logging.LogUtils.getLogger().info("MASTER_DIAMOND_NATIVE_PASSED: actual12native correct-tool Overworld diamond removals across3distinct Master chunk regions, oldJourneyman/two-region/replay refusals/20earned3600XP and old16+3Nether proofs retained; supplied tools/future native terrain only, no source/count/quest/XP/rank injection");h.succeed();
 }
}
